import sys

def is_hill_number(n):
    s = str(n)
    i = 0
    while i < len(s) - 1 and s[i] <= s[i + 1]:
        i += 1
    while i < len(s) - 1 and s[i] >= s[i + 1]:
        i += 1
    return i == len(s) - 1

def count_hill_numbers(limit):
    def count_up_to(length, is_peak_reached, prev_digit, limit_str, index):
        if length == index:
            return 1 if is_peak_reached else 0
        count = 0
        start = 1 if index == 0 else 0
        limit_digit = int(limit_str[index])
        for digit in range(start, min(10, limit_digit + 1)):
            if is_peak_reached or digit <= prev_digit:
                new_limit_str = limit_str if digit == limit_digit else '9' * (length - index - 1)
                count += count_up_to(length, is_peak_reached or digit < prev_digit, digit, new_limit_str, index + 1)
        return count

    total_count = 0
    limit_str = str(limit)
    for length in range(1, len(limit_str) + 1):
        total_count += count_up_to(length, False, 0, limit_str[:length], 0)
    return total_count

n = int(sys.stdin.read().strip())
if not is_hill_number(n):
    print(-1)
else:
    print(count_hill_numbers(n))
